mapper.insert:
insert into BOK_SUBJECT(BOOKSET_ID,SUBJECT_NO,SUBJECT_NAME,FSUBJECT_ID,SUBJECT_TYPE,SUBJECT_LEVEL,BAL_FLAG,DATA_SOURCE,STATUS,REMARK,ERR_MSG,CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME) select * from ( select TEMP.* from (
SELECT #{bokSubject.booksetId} BOOKSET_ID,#{bokSubject.subjectNo} SUBJECT_NO,#{bokSubject.subjectName} SUBJECT_NAME,#{bokSubject.fsubjectId} FSUBJECT_ID, #{bokSubject.subjectType} SUBJECT_TYPE,#{bokSubject.subjectLevel} SUBJECT_LEVEL,#{bokSubject.balFlag} BAL_FLAG,#{bokSubject.dataSource} DATA_SOURCE, #{bokSubject.status} STATUS,#{bokSubject.remark} REMARK,#{bokSubject.errMsg} ERR_MSG,#{bokSubject.createUser} CREATE_USER, #{bokSubject.createDept} CREATE_DEPT,#{bokSubject.createTime} CREATE_TIME,#{bokSubject.updateUser} UPDATE_USER,#{bokSubject.updateTime} UPDATE_TIME from dual
)TEMP where not EXISTS ( select 1 from BOK_SUBJECT a where a.BOOKSET_ID = TEMP.BOOKSET_ID AND a.SUBJECT_NO = TEMP.SUBJECT_NO ) ) a; update BOK_SUBJECT a,( select * from ( select TEMP.* from (
SELECT #{bokSubject.booksetId} BOOKSET_ID,#{bokSubject.subjectNo} SUBJECT_NO,#{bokSubject.subjectName} SUBJECT_NAME,#{bokSubject.fsubjectId} FSUBJECT_ID, #{bokSubject.subjectType} SUBJECT_TYPE,#{bokSubject.subjectLevel} SUBJECT_LEVEL,#{bokSubject.balFlag} BAL_FLAG,#{bokSubject.dataSource} DATA_SOURCE, #{bokSubject.status} STATUS,#{bokSubject.remark} REMARK,#{bokSubject.errMsg} ERR_MSG,#{bokSubject.createUser} CREATE_USER, #{bokSubject.createDept} CREATE_DEPT,#{bokSubject.createTime} CREATE_TIME,#{bokSubject.updateUser} UPDATE_USER,#{bokSubject.updateTime} UPDATE_TIME from dual
)TEMP
) a )b set a.SUBJECT_NAME = b.SUBJECT_NAME, a.FSUBJECT_ID = b.FSUBJECT_ID, a.SUBJECT_TYPE = b.SUBJECT_TYPE, a.SUBJECT_LEVEL = b.SUBJECT_LEVEL, a.BAL_FLAG = b.BAL_FLAG, a.STATUS = b.STATUS, a.REMARK = b.REMARK, a.ERR_MSG = b.ERR_MSG, a.UPDATE_USER = b.UPDATE_USER, a.UPDATE_TIME = b.UPDATE_TIME where a.BOOKSET_ID = b.BOOKSET_ID and a.SUBJECT_NO = b.SUBJECT_NO

mapper.select:
select BS.BOOKSET_ID as booksetId, BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId, BS.SUBJECT_TYPE as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.BAL_FLAG as balFlag, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime, BS.UPDATE_TIME as updateDate, BS.DATA_SOURCE as dataSource, BS.STATUS as statusValid, BS.REMARK as remark, BS.ERR_MSG as errMsg from BOK_SUBJECT BS
BS.SUBJECT_LEVEL = #{subjectLevel}
AND BS.BAL_FLAG = #{balFlag}
AND BS.FSUBJECT_ID = #{fsubjectId}
AND BS.SUBJECT_NO like concat(#{subjectNo} ,'%')
AND BS.SUBJECT_NAME like concat('%',#{subjectName},'%')
AND BS.SUBJECT_TYPE = #{subjectType}
AND BS.STATUS = #{status}
order by BS.BOOKSET_ID,BS.SUBJECT_NO,BS.SUBJECT_LEVEL

select BS.BOOKSET_ID as booksetId, BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId,
BS.SUBJECT_TYPE as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.BAL_FLAG as balFlag, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime, BS.UPDATE_TIME as updateDate, BS.DATA_SOURCE as dataSource, BS.STATUS as statusValid, BS.REMARK as remark, BS.ERR_MSG as errMsg from BOK_SUBJECT BS
SUBJECT_NO = #{subjectNo}
AND BOOKSET_ID = #{booksetId}
